import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest cases -------------------------------------------------
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
  });
  it("a single plain sword → premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
  });
  it("a single plain amulet → premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
        },
      ],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
  });
  it("a single plain staff → premium 93 G (80 base + 8 first insurance + 5 fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "staff", material: "oak", enchantment: 2, cursed: false }],
        },
      ],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
  });
  it("a single plain potion → premium 49 G (40 base + 4 first insurance + 5 fee)", () => {
    const scenario = {
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "potion", material: "glass", enchantment: 1, cursed: false }],
        },
      ],
    };

    expect(runScenario(scenario)).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Components and blocks -------------------------------------------------
  it.todo("a single rune → base premium 25 G");
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Individual premium modifiers -----------------------------------------
  it.todo("cursed items add a 50 % risk surcharge to the item's base premium");
  it.todo("enchantment level 5 adds a 30 % high-enchantment surcharge");
  it.todo("enchantment level 4 adds no high-enchantment surcharge");
  it.todo("a cursed sword with exactly enchantment 5 gets both surcharges");
  it.todo("a customer with exactly 2 years with MHPCO gets the 20 % loyalty discount");
  it.todo("a customer with 1 year with MHPCO gets no loyalty discount");
  it.todo("the second contract of a scenario gets the 15 % follow-up discount");

  // --- Modifier scope on multi-item policies --------------------------------
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → curse adds 50 G on the item only → 210 G before further modifiers and fee",
  );

  // --- Rounding --------------------------------------------------------------
  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");

  // --- Claim: standard reimbursement ----------------------------------------
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");

  // --- Claim: special clauses ------------------------------------------------
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Claim: deductible per damage event -----------------------------------
  it.todo(
    "dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)",
  );

  // --- Cap -------------------------------------------------------------------
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G");
  it.todo("two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type --------------------------------------
  it.todo("two swords insured, both damaged → each damage entry gets its own deductible");
  it.todo("more damage entries of a type than insured → error (non-zero exit)");

  // --- Error cases -----------------------------------------------------------
  it.todo("quote with an unknown item type (broomstick) → error");
  it.todo("claim referencing an item not part of the policy → error");
  it.todo("claim with a damage entry of an unknown item type → error");
  it.todo("claim with a damage entry amount -200 → error");

  // --- Integration examples --------------------------------------------------
  it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("3-year customer's second quote, cursed sword enchantment 7 → premium 160 G");

  // --- CLI -------------------------------------------------------------------
  it.todo("CLI reads the schema example from stdin and writes results to stdout");
  it.todo("CLI exits non-zero and writes to stderr on an unknown item type, with no results on stdout");
});

