const PROCESSING_FEE = 5;

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Step = {
  op: string;
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type StepResult = {
  premium: number;
};

export type ScenarioResults = {
  results: StepResult[];
};

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

// Percentages are applied as `amount * percent / 100` rather than
// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const withFirstInsuranceSurcharge = (base: number): number =>
  base + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);

const itemPremium = (item: Item): number =>
  withFirstInsuranceSurcharge(basePremium(item));

// Amounts are rounded in the MHPCO's favor: premiums round up.
const roundPremium = (amount: number): number => Math.ceil(amount);

const quote = (step: Step): StepResult => ({
  premium: roundPremium(
    step.items.reduce(
      (total, item) => total + itemPremium(item),
      PROCESSING_FEE,
    ),
  ),
});

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(quote),
});

