const PROCESSING_FEE = 5;

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Step = {
  op: string;
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type StepResult = {
  premium: number;
};

export type ScenarioResults = {
  results: StepResult[];
};

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

// Percentages are applied as `amount * percent / 100` rather than
// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const withFirstInsuranceSurcharge = (base: number): number =>
  base + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

// A building block of 3 alike components is offered at a flat rate.
//
// Provisional: this only checks the item count, not that the 3 items are alike
// or even that they are components. That is all the current tests pin down. The
// general rule (group by type, price each group of 3 as a block, the remainder
// individually) is still to be driven out by the pending block tests.
const itemsBasePremium = (items: Item[]): number => {
  if (items.length === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
  return items.reduce((total, item) => total + basePremium(item), 0);
};

const itemsPremium = (items: Item[]): number =>
  withFirstInsuranceSurcharge(itemsBasePremium(items));

// Amounts are rounded in the MHPCO's favor: premiums round up.
const roundPremium = (amount: number): number => Math.ceil(amount);

const quote = (step: Step): StepResult => ({
  premium: roundPremium(PROCESSING_FEE + itemsPremium(step.items)),
});

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(quote),
});

