    : 0;
  return withFirstInsuranceSurcharge(policyBase) + loyalty;
};

const policyPremium = (items: Item[], customer: Customer): number =>
  withPolicyModifiers(itemsBasePremium(items), customer) +
  sumOf(items, itemSurcharges);

