const groupByType = (items: Item[]): Item[][] => {
  const groupsByType = new Map<string, Item[]>();
  for (const item of items) {
    const alike = groupsByType.get(item.type) ?? [];
    alike.push(item);
    groupsByType.set(item.type, alike);
  }
  return [...groupsByType.values()];
